mapper.select:
select
    tm.Smt_Name as smtName,
    tm.Smt_Code as smtCode,
    u1.U_Name as uName,
    mn.*
from Sys_Message_Shield mn
left join Sys_Message_Temp tm on mn.Smt_Id=tm.id
left join SYS_User u1 on u1.U_Id=mn.U_Id

    
        and mn.Ms_Send_Sys=#{params.msSendSys}
    
    
        and mn.Ms_Send_Sms=#{params.msSendSms}
    
    
        and mn.Smt_Id=#{params.smtId}
    
    
        and mn.U_Id=#{params.uId}
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and INSTR(u1.U_Name,#{params.uName})
    
    
        and INSTR(tm.Smt_Name,#{params.smtName})
    
    
        and INSTR(tm.Smt_Code,#{params.smtCode})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
